  "Choose α, the probability of a Type I error: rejecting H0 when it is actually true." = "اختر α، وهو احتمال الخطأ من النوع الأول: رفض H0 وهي صحيحة فعلًا.",
  "Significance level α" = "مستوى الدلالة α", "The question does not state α, so the usual α = 0.05 is filled in. Change it if your instructor uses another level." = "لا يذكر السؤال α، لذا وُضعت القيمة المعتادة α = 0.05. غيّرها إذا كان مدرّسك يستخدم مستوى آخر.",
  "α (Type I error)" = "α (الخطأ من النوع الأول)", "Confidence level for intervals, 1 − α" = "مستوى الثقة للفترات، 1 − α",
  "Collect what is known about the groups and the data, and check whether the group variances are equal: this decides between the one-way ANOVA and the Welch ANOVA. The other assumptions are checked on the residuals after the test." = "اجمع ما هو معروف عن المجموعات والبيانات، وتحقّق من تساوي تباينات المجموعات: وهذا يحسم الاختيار بين تحليل التباين أحادي الاتجاه وتحليل ويلش. أما بقية الافتراضات فتُفحص على البواقي بعد الاختبار.",
  "Collect what is known about the populations and the samples, check independence and normality, and choose between a parametric and a non-parametric test." = "اجمع ما هو معروف عن المجتمعات والعيّنات، وافحص الاستقلالية والطبيعية، ثم اختر بين اختبار معلمي وآخر لامعلمي.",
  "Collect what is known about the population and the sample, check normality, and choose between a parametric and a non-parametric test." = "اجمع ما هو معروف عن المجتمع والعيّنة، وافحص الطبيعية، ثم اختر بين اختبار معلمي وآخر لامعلمي.",
  "Collect what is known about the design and the data. No assumption test is run here: the ANOVA comes first, and its assumptions are checked on the residuals after the test." = "اجمع ما هو معروف عن التصميم والبيانات. لا يُجرى هنا اختبار للافتراضات: يأتي تحليل التباين أولًا، وتُفحص افتراضاته على البواقي بعد الاختبار.",
  "Type of test" = "نوع الاختبار", "Decide from the information" = "القرار بحسب المعلومات", "Population σ, if known" = "σ للمجتمع، إن كان معلومًا", "Population σ1, if known" = "σ1 للمجتمع الأول، إن كان معلومًا", "Population σ2, if known" = "σ2 للمجتمع الثاني، إن كان معلومًا",
  "Equal variances?" = "هل التباينات متساوية؟", "Decide with the F test" = "القرار باختبار F", "Assume equal" = "افتراض التساوي", "Assume unequal" = "افتراض عدم التساوي",
  "Test for equal group variances" = "اختبار تساوي تباينات المجموعات", "Levene (median)" = "اختبار ليفين (الوسيط)", "Bartlett" = "اختبار بارتليت", "Decide with the test" = "القرار بالاختبار",
  "Assume equal (one-way ANOVA)" = "افتراض التساوي (تحليل التباين أحادي الاتجاه)", "Assume unequal (Welch ANOVA)" = "افتراض عدم التساوي (تحليل ويلش)",
  "How this problem is analysed" = "كيف تُحلَّل هذه المسألة", "6 · Decision" = "6 · القرار", "7 · Post-hoc (only if H0 is rejected)" = "7 · الاختبارات البعدية (فقط إذا رُفضت H0)", "8 · Assumption checks" = "8 · فحص الافتراضات",
  "What we know" = "ما نعرفه", "The data" = "البيانات", "Plots of the data" = "رسوم البيانات",
  "Look at the data before testing: the main-effects plot shows how the mean response changes with each factor, the interaction plots show whether the effect of one factor depends on the level of another (non-parallel lines), and the boxplots show the spread of every treatment combination." =
    "انظر إلى البيانات قبل الاختبار: يوضّح مخطط الآثار الرئيسية كيف يتغير متوسط الاستجابة مع كل عامل، وتوضّح مخططات التفاعل هل يعتمد أثر عامل على مستوى عامل آخر (خطوط غير متوازية)، وتوضّح المخططات الصندوقية تشتت كل توليفة من المعالجات.",
  "Main-effects plot" = "مخطط الآثار الرئيسية", "Interaction plots" = "مخططات التفاعل", "Boxplots by treatment combination" = "مخططات صندوقية لكل توليفة معالجات"
)

